/** Runs fresh engines in sequence and reads their stores only after all runners join. */
class IterationDriver internal constructor(
    private val policy: IterationPolicy,
    private val shared: SharedObjects,
    private val budget: Duration,
    private val invokeRun: (RunConfig, SharedObjects, Duration) -> RunResult<RunMethodAnalyzer>,
    private val guardBarrier: (SharedObjects, () -> Next) -> Next,
) {
    constructor(policy: IterationPolicy, shared: SharedObjects, budget: Duration) :
        this(policy, shared, budget, ::runEngine, ::withBarrierGuard)

    private val run1MarkMode = readRun1MarkMode()
    private val fieldLimitSchedule = policy.fieldLimitSchedule
    private val frontierLog = ArrayList<Frontier>()
    val frontiers: List<Frontier> get() = Collections.unmodifiableList(ArrayList(frontierLog))

    fun analyze(roots: List<MethodKey>): Report {
        val start = TimeSource.Monotonic.markNow()
        val report = ReportBuilder()
        var index = 1
        fun end(status: RunStatus, reason: EndReason): Report {
            logger.info { "BIDI_ANALYSIS_END run=$index status=$status reason=$reason elapsed=${start.elapsedNow()}" }
            return report.build(AnalysisEnd(status, index,
                if (index % 2 == 1) Direction.FORWARD else Direction.BACKWARD, reason, run1MarkMode))
        }
        try {
            logger.info { "BIDI_FIELD_LIMIT_SCHEDULE schedule=$fieldLimitSchedule" }
            val firstLimit = policy.fieldLimit(1)
            require(firstLimit == 1) { "F78: selected run 1 needs field limit exactly 1" }
            var config = RunConfig(1, firstLimit, demand = null, records = shared.records.view(),
                seeds = SeedIndex.EMPTY, roots = roots, run1MarkMode = run1MarkMode,
                fieldLimitSchedule = fieldLimitSchedule)
            while (true) {
                index = config.index
                val selectedTimeout = policy.timeout(config, budget - start.elapsedNow())
                // The callback consumes this same budget and cannot extend it.
                val timeout = minOf(selectedTimeout, budget - start.elapsedNow())
                when (val next = runOnce(config, report, timeout)) {
                    is Next.Run -> config = next.config
                    is Next.End -> return end(next.status, next.reason)
                }
            }
        } catch (error: Throwable) {
            logger.error(error) { "Run $index failed; the analysis ends with the report so far" }
            return end(RunStatus.FAILED, EndReason.ABNORMAL)
        }
    }

    /** This frame releases its result before the next engine is created. */
    private fun runOnce(config: RunConfig, report: ReportBuilder, timeout: Duration): Next {
        val start = TimeSource.Monotonic.markNow()
        logger.info { "BIDI_RUN_START run=${config.index} direction=${config.direction} limit=${config.fieldLimit} timeout=$timeout markMode=${config.mode.markMode}" }
        logOptimizationStatistics(config, "START")
        val result = try {
            invokeRun(config, shared, timeout)
        } catch (error: Throwable) {
            logger.info { "BIDI_RUN_END run=${config.index} status=FAILED engineTime=${start.elapsedNow()}" }
            logOptimizationStatistics(config, "END")
            throw error
        } finally {
            // Diagnostic counters only. Engine workers have joined before this callback returns.
            LoopPipelineTrace.finishRun(config.index)
        }
        logger.info { "BIDI_JOINED_RELEASE run=${config.index} sealReleaseTime=${result.joinedSealReleaseTime} status=${result.status}" }
        val engineTime = (start.elapsedNow() - result.joinedStaticBindingTime).coerceAtLeast(Duration.ZERO)
        logger.info { "BIDI_RUN_END run=${config.index} status=${result.status} engineTime=$engineTime" }
        if (config.run1 && config.mode.markMode == MarkMode.FULL && result.status == RunStatus.COMPLETE) {
            logger.info { "BIDI_FLOW_BACKED_STATISTICS run=${config.index} neutralBatches=${result.analyzers.sumOf { it.neutralBatchApplications }} neutralMemberships=${result.analyzers.sumOf { it.neutralBatchMemberships }} bulkStorePackets=${result.analyzers.sumOf { it.neutralBulkStorePackets }} bulkStoreMemberships=${result.analyzers.sumOf { it.neutralBulkStoreMemberships }} scalarStoreFallbackMemberships=${result.analyzers.sumOf { it.neutralScalarFallbackMemberships }}" }
        }
        if (shared.n2Statistics != null && result.status == RunStatus.COMPLETE) {
            logger.info {
                "BIDI_CFG_DELIVERY_STATISTICS run=${config.index} hits=${result.analyzers.sumOf { it.cfgDeliveryHits }} " +
                    "searches=${result.analyzers.sumOf { it.cfgDeliverySearches }} " +
                    "visitedNodes=${result.analyzers.sumOf { it.cfgDeliveryVisitedNodes }} " +
                    "destinations=${result.analyzers.sumOf { it.cfgDeliveryDestinations }} " +
                    "maxWidth=${result.analyzers.maxOfOrNull { it.cfgDeliveryMaxWidth } ?: 0}"
            }
        }
        if (shared.n2Statistics != null) {
            val loopMethods = result.analyzers.mapNotNull { actor -> actor.blockDiagnostics()?.let { actor to it } }
            logger.info { "BIDI_LOOP_BLOCK_STATISTICS run=${config.index} methods=${loopMethods.size}" }
            for ((actor, summary) in loopMethods.sortedByDescending { it.first.steps }.take(24)) logger.info {
                "BIDI_LOOP_BLOCK_METHOD run=${config.index} method=${actor.key} $summary"
            }
            val measured = result.analyzers.mapNotNull { actor -> actor.bodyWorkSnapshot?.let { actor.key to it } }
            logger.info {
                "BIDI_BODY_WORK_STATISTICS run=${config.index} scope=packet-events " +
                    "snapshotActors=${measured.size} unavailableActors=${result.analyzers.size - measured.size} " +
                    "processed=${measured.sumOf { it.second.processedPackets }} " +
                    "freshPostS=${measured.sumOf { it.second.freshPackets }} " +
                    "candidateOffers=${measured.sumOf { it.second.candidatePackets }} " +
                    "methodCandidateOffers=${measured.sumOf { it.second.methodCandidatePackets }} " +
                    "blockCandidateOffers=${measured.sumOf { it.second.blockCandidatePackets }} " +
                    "cyclicProcessed=${measured.sumOf { it.second.cyclicProcessedPackets }} " +
                    "cyclicFreshPostS=${measured.sumOf { it.second.cyclicFreshPackets }} " +
                    "sampledPackets=${(0..2).map { stage -> measured.sumOf { it.second.sampledPackets[stage] } }} " +
                    "sampledMemberships=${(0..2).map { stage -> measured.sumOf { it.second.sampledMemberships[stage] } }} " +
                    "droppedSamples=${measured.sumOf { it.second.droppedSamples }}"
            }
            val hot = (measured.sortedByDescending { it.second.processedPackets }.take(12) +
                measured.sortedByDescending { it.second.candidatePackets }.take(12)).distinctBy { it.first }
            for ((method, snapshot) in hot) logger.info {
                "BIDI_BODY_WORK_METHOD run=${config.index} method=$method snapshot=$snapshot"
            }
            // Only copied IDs from bounded hot-method samples enter this read-only dictionary.
            val fieldIds = hot.asSequence().flatMap { it.second.samples.asSequence() }.flatMap { sample ->
                (sample.firstPath + sample.initials.flatMap { it.path }).asSequence()
            }.distinct().take(256).toList()
            val markIds = hot.asSequence().flatMap { it.second.samples.asSequence() }.flatMap { sample ->
                (sample.exampleMarkIds + sample.initials.mapNotNull { it.concreteMark }).asSequence()
            }.distinct().take(256).toList()
            for (id in fieldIds) logger.info {
                "BIDI_BODY_FIELD run=${config.index} id=$id accessor=${shared.ap.accessors.accessor(id)}"
            }
            for (id in markIds) logger.info {
                "BIDI_BODY_MARK run=${config.index} id=$id name=${shared.ap.marks.name(TaintMark(id))} key=${shared.ap.marks.key(TaintMark(id))}"
            }
            // These are scalar-store end-state gauges, not cumulative edge work.
            // Cancelled/live actors need a heap census; absent snapshots are not zero.
            val snapshots = result.analyzers.mapNotNull { it.scalarIdentityStatistics }
            val reasons = sortedMapOf<String, Long>()
            for (snapshot in snapshots) for ((reason, count) in snapshot.fallbackReasons)
                reasons[reason] = (reasons[reason] ?: 0L) + count
            logger.info {
                "BIDI_IDENTITY_STORAGE_STATISTICS run=${config.index} scope=frozen-scalar-stores " +
                    "snapshotActors=${snapshots.size} unavailableActors=${result.analyzers.size - snapshots.size} " +
                    "compactPoints=${snapshots.sumOf { it.compactPoints }} " +
                    "compactNormal=${snapshots.sumOf { it.compactNormal }} compactDemand=${snapshots.sumOf { it.compactDemand }} " +
                    "compactFlow=${snapshots.sumOf { it.compactFlow }} compactTaint=${snapshots.sumOf { it.compactTaint }} " +
                    "protectedNormal=${snapshots.sumOf { it.protectedNormal }} protectedDemand=${snapshots.sumOf { it.protectedDemand }} " +
                    "fullPoints=${snapshots.sumOf { it.fullPoints }} promotedPoints=${snapshots.sumOf { it.promotedPoints }} " +
                    "firstFullPoints=${snapshots.sumOf { it.firstFullPoints }} bitWords=${snapshots.sumOf { it.bitWords }} " +
                    "fullArrayCapacity=${snapshots.sumOf { it.fullArrayCapacity }} fallbackReasons=$reasons"
            }
        }
        logOptimizationStatistics(config, "END")
        config.demand?.staticCompletionStatistics()?.let {
            logger.info { "BIDI_STATIC_CLOSURE_LOOKUP run=${config.index} $it" }
        }
        config.demand?.diagnosticC5Samples()?.forEach { sample ->
            logger.info { "BIDI_C5_ROW_SAMPLE run=${config.index} $sample" }
        }
        if (result.status != RunStatus.COMPLETE) return Next.End(result.status)
        val barrierStart = TimeSource.Monotonic.markNow()
        val next = try {
            guardBarrier(shared) { barrier(config, result, report) }
        } catch (error: Cancellation.Cancelled) {
            Next.End(RunStatus.OOM)
        } finally {
            logger.info { "BIDI_BARRIER_END run=${config.index} barrierTime=${barrierStart.elapsedNow()} iterationTime=${start.elapsedNow()}" }
            if (config.run1) shared.releaseRun1CatalogCoverage()
        }
        if (shared.cancellation.isActive()) return next
        logger.error { "Run ${config.index}: the barrier memory guard fired; the analysis ends with the report so far" }
        return Next.End(RunStatus.OOM)
    }

    private fun logOptimizationStatistics(config: RunConfig, phase: String) {
        shared.abstractionStatistics?.let { statistics ->
            logger.info { "BIDI_ABSTRACTION_STATISTICS run=${config.index} direction=${config.direction} limit=${config.fieldLimit} phase=$phase totals=${statistics.snapshot()}" }
        }
        shared.n1Statistics?.let { statistics ->
            logger.info { "BIDI_N1_STATISTICS run=${config.index} direction=${config.direction} limit=${config.fieldLimit} phase=$phase totals=${statistics.snapshot()}" }
        }
        shared.n2Statistics?.let { statistics ->
            logger.info { "BIDI_N2_STATISTICS run=${config.index} direction=${config.direction} limit=${config.fieldLimit} phase=$phase totals=${statistics.snapshot()}" }
        }
        shared.requestBatchStatistics?.let { statistics ->
            logger.info { "BIDI_REQUEST_BATCH_STATISTICS run=${config.index} direction=${config.direction} limit=${config.fieldLimit} phase=$phase totals=${statistics.snapshot()}" }
        }
    }

    private fun barrier(config: RunConfig, result: RunResult<RunMethodAnalyzer>, report: ReportBuilder): Next {
        if (shared.n2Statistics != null) {
            val censusStart = TimeSource.Monotonic.markNow()
            val publicAdmitted = result.analyzers.fold(RelationCensus()) { counts, actor -> counts + actor.summaries.census() }
            val publicOutgoing = result.analyzers.fold(RelationCensus()) { counts, actor -> counts + actor.summaries.demandCensus(config.direction) }
            val blockAdmitted = result.analyzers.asSequence().flatMap { it.blockSummaries() }
                .fold(RelationCensus()) { counts, block -> counts + block.summaries.census() }
            val blockOutgoing = result.analyzers.asSequence().flatMap { it.blockSummaries() }
                .fold(RelationCensus()) { counts, block -> counts + block.summaries.demandCensus(config.direction) }
            val admitted = publicAdmitted + blockAdmitted
            val outgoing = publicOutgoing + blockOutgoing
            logger.info { "BIDI_FLOW_BACKED_CENSUS run=${config.index} admitted=$admitted outgoing=$outgoing blockAdmitted=$blockAdmitted blockOutgoing=$blockOutgoing scanTime=${censusStart.elapsedNow()}" }
        }
        val forward = config.direction == Direction.FORWARD
        val terminals = report.prepare(config, result, shared)
        shared.records.persist(config.direction, result.analyzers.asSequence().map { it.key to it.summaries })
        shared.records.persistScoped(config.direction, result.analyzers.asSequence().flatMap { it.blockSummaries() })
        val handOff = HandOff.of(config, result, shared)
        val frontier = frontierOf(config, result, handOff, terminals.entries.size)
        frontierLog += frontier
        frontier.log()
        val next = when {
            forward && handOff.demandEdges.isEmpty() -> Next.End(RunStatus.COMPLETE, EndReason.NO_DEMAND_EDGE)
            forward && !policy.continueAfter(config, result, frontiers) -> Next.End(RunStatus.COMPLETE, EndReason.POLICY)
            else -> Next.Run(nextConfig(config, handOff, terminals.normal))
        }
        logger.info { "BIDI_TARGET_STATISTICS run=${config.index} raw=${result.analyzers.sumOf { it.targets.size }} outgoing=${result.analyzers.sumOf { it.outgoingTargets.size }} reports=${terminals.entries.size} blockRaw=${result.analyzers.asSequence().flatMap { it.blockTargets() }.sumOf { it.rows.size }} blockOutgoing=${result.analyzers.asSequence().flatMap { it.blockOutgoingTargets() }.sumOf { it.rows.size }}" }
        // All fallible preparation precedes this single terminal/report commit.
        shared.cancellation.checkpoint()
        if (forward && config.mode.markMode == MarkMode.FULL) {
            shared.normalRuleContributors.publish(result.analyzers.asSequence()
                .flatMap { it.normalContributorRows() }.asIterable())
        }
        report.commit(terminals)
        return next
    }

    private fun nextConfig(config: RunConfig, handOff: HandOff, normalTargets: org.opentaint.dataflow.bidi.engine.NormalTargetView): RunConfig {
        val index = config.index + 1
        val limit = policy.fieldLimit(index)
        require(limit >= config.fieldLimit) { "ap.md W3: the field limit must not decrease" }
        return RunConfig(index, limit, handOff.demand, shared.records.view(), handOff.seeds, config.roots,
            run1MarkMode = run1MarkMode, fieldLimitSchedule = fieldLimitSchedule, normalTargets = normalTargets)
    }

    companion object : KLogging() {
        const val BARRIER_MEMORY_THRESHOLD = 0.99
    }
}

private fun runEngine(config: RunConfig, shared: SharedObjects, timeout: Duration): RunResult<RunMethodAnalyzer> =
    RunManager(config, shared, RunMethodHandlers(MethodLocalServicesFactory(::RunMethodLocalServices),
        MethodCallServicesFactory(::RunMethodCallServices))).run(timeout)

private fun withBarrierGuard(shared: SharedObjects, body: () -> Next): Next =
    MemoryManager(shared.refManager, IterationDriver.BARRIER_MEMORY_THRESHOLD) { shared.cancellation.cancel() }
        .runWithMemoryManager(body)

package org.opentaint.dataflow.bidi.driver

import org.opentaint.dataflow.bidi.ap.Direction
import org.opentaint.dataflow.bidi.ap.MarkMode
import org.opentaint.dataflow.bidi.engine.*
import java.util.Collections

enum class EndReason { STOP_RULE, NO_DEMAND_EDGE, POLICY, ABNORMAL }

data class AnalysisEnd(
    val status: RunStatus, val run: Int, val direction: Direction, val reason: EndReason,
    val run1MarkMode: MarkMode = MarkMode.FULL,
)

/** Only settled configured-root ZERO terminal identities enter the report. */
class Report(entries: List<Entry>, val end: AnalysisEnd) {
    val entries: List<Entry> = Collections.unmodifiableList(ArrayList(entries))
    data class Entry(val id: ReportId, val descriptor: ReportDescriptor)
}

/** One completed driver barrier commits retained relations and root reports together. */
class ReportBuilder {
    class Snapshot internal constructor(val normal: NormalTargetView, entries: Map<ReportId, Report.Entry>) {
        internal val entries = Collections.unmodifiableMap(LinkedHashMap(entries))
    }
    private var state = Snapshot(NormalTargetView.EMPTY, emptyMap())
    val normalTargets: NormalTargetView get() = state.normal
    val reportCount: Int get() = state.entries.size

    fun prepare(config: RunConfig, result: RunResult<RunMethodAnalyzer>, shared: SharedObjects): Snapshot {
        check(result.status == RunStatus.COMPLETE)
        if (config.direction != Direction.FORWARD) return state
        val entries = LinkedHashMap(state.entries)
        for (actor in result.analyzers) {
            shared.cancellation.checkpoint()
            if (actor.key !in config.roots) continue
            for (row in actor.targets) {
                val target = row.target as? Target.NormalTarget ?: continue
                if (row.premise.isZero) entries.putIfAbsent(target.id,
                    Report.Entry(target.id, shared.reportCatalog.descriptor(target.id)))
            }
        }
        val fresh = result.analyzers.asSequence().flatMap { actor ->
            actor.targets.asSequence().mapNotNull { row ->
                (row.target as? Target.NormalTarget)?.let { OwnedNormalTarget(actor.key, row.premise, it.id) }
            }
        }
        val local = result.analyzers.asSequence().flatMap { it.blockTargets() }.flatMap { block ->
            block.rows.asSequence().mapNotNull { row ->
                (row.target as? Target.NormalTarget)?.let {
                    OwnedNormalTarget(block.method, row.premise, it.id, block.scope)
                }
            }
        }
        val normal = NormalTargetStore(shared.ap, state.normal.rows() + fresh + local)
        check(normal.zeroRows().all { it.id in entries }) {
            "Every retained ZERO terminal must reach a configured root before the barrier"
        }
        return Snapshot(normal, entries)
    }

    fun commit(prepared: Snapshot) { state = prepared }
    fun build(end: AnalysisEnd): Report = Report(state.entries.values.toList(), end)
}

package org.opentaint.dataflow.bidi.driver

import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.bidi.engine.RunConfig
import org.opentaint.dataflow.bidi.engine.RunMethodAnalyzer
import org.opentaint.dataflow.bidi.engine.RunResult
import org.opentaint.dataflow.bidi.engine.RunStatus
import org.opentaint.dataflow.bidi.engine.SharedObjects
import org.opentaint.dataflow.bidi.interp.SinkRule
import org.opentaint.dataflow.bidi.store.DemandStore
import org.opentaint.dataflow.bidi.store.FrozenStaticCompletion
import org.opentaint.dataflow.bidi.store.guidancePattern
import org.opentaint.dataflow.bidi.store.DemandEntry
import org.opentaint.dataflow.bidi.store.DemandExit
import org.opentaint.dataflow.bidi.store.PairedDemand
import org.opentaint.ir.api.common.cfg.CommonInst
import java.util.Collections
import mu.KotlinLogging
import kotlin.time.TimeSource

/** Immutable outgoing demand, seeds and accepted explicit-pattern counts.
 * [of] counts only successful normalized builder insertions. Its method-key support is
 * empty exactly when the built explicit snapshot is empty; virtual static families are separate.
 * Manually constructed test values need not have that binding.
 */
class HandOff(val demand: DemandStore, val seeds: SeedIndex, demandEdges: Map<MethodKey, Int>) {
    val demandEdges: Map<MethodKey, Int> = Collections.unmodifiableMap(LinkedHashMap(demandEdges))

    companion object {
        private val logger = KotlinLogging.logger {}
        fun of(config: RunConfig, result: RunResult<RunMethodAnalyzer>, shared: SharedObjects): HandOff {
            check(result.status == RunStatus.COMPLETE) { "A hand-off needs a complete run" }
            shared.cancellation.checkpoint()
            val counts = LinkedHashMap<MethodKey, Int>()
            val (demand, seeds) = if (config.direction == Direction.FORWARD)
                toBackward(result, shared, counts, config.run1) else toForward(result, shared, counts)
            return HandOff(demand, seeds, counts)
        }

        private inline fun forEachDemandPiece(result: RunResult<RunMethodAnalyzer>, shared: SharedObjects,
                                             direction: Direction,
                                             body: (MethodKey, PremiseKey, Pattern) -> Unit) {
            for (actor in result.analyzers) {
                shared.cancellation.checkpoint()
                for ((premise, facts) in actor.summaries.demandEdges(direction)) {
                    shared.cancellation.checkpoint()
                    if (!actor.mode.run1 && facts is FlowTree && facts.layer == Layer.DEMAND)
                        check(facts.tail == Tail.ANY && facts.exclusion == ExclusionSet.Empty) {
                            "A restricted FLOW demand result must be ANY with empty field exclusions"
                        }
                    for (leaf in shared.ops.leaves(facts)) {
                        shared.cancellation.checkpoint()
                        body(actor.key, premise, leaf)
                    }
                }
            }
        }

        private fun toBackward(result: RunResult<RunMethodAnalyzer>, shared: SharedObjects,
                               counts: MutableMap<MethodKey, Int>, run1: Boolean): Pair<DemandStore, SeedIndex> {
            val demand = DemandStore.Builder(shared.ap)
            val completionStart = TimeSource.Monotonic.markNow()
            val joinedCompletion = if (run1) result.staticCompletion else null
            val completion = if (run1 && joinedCompletion == null)
                FrozenStaticCompletion.Builder(shared.ap, shared.staticCallGraph) else null
            if (run1) demand.withSharedStaticCarry()
            if (joinedCompletion != null) {
                demand.withCompletion(joinedCompletion)
                for ((owner, view) in joinedCompletion.scopedViews())
                    demand.withCompletion(owner.method, owner.local, view)
                logger.info { "BIDI_STATIC_CLOSURE_HANDOFF run=1 source=JOINED ${joinedCompletion.statistics()}" }
            }
            // Synthetic frozen RunResults in small tests have no runner-owned
            // pre-release phase. Their fallback uses local seeds only; real
            // RunManager results supply the joined completion above.
            if (completion != null) {
                for (actor in result.analyzers) {
                    for (edge in actor.staticGuidanceSeeds.frozenRows()) {
                        shared.cancellation.checkpoint()
                        completion.addSeed(actor.key, edge)
                    }
                    for (key in actor.freezeStaticWriteCandidates().lostRows()) {
                        shared.cancellation.checkpoint()
                        completion.addSeed(actor.key, key.original.toPattern(), key.result)
                    }
                    for (terminal in actor.outgoingTargets) {
                        shared.cancellation.checkpoint()
                        check(terminal.target == org.opentaint.dataflow.bidi.engine.Target.DemandTarget)
                        val original = checkNotNull(terminal.premise as? InitialAp) { "Run-1 cannot retain an ND original" }
                        completion.addTarget(actor.key, original.toPattern())
                    }
                }
            }
            val seedCaptureTime = completionStart.elapsedNow()
            val projectionStart = TimeSource.Monotonic.markNow()
            forEachDemandPiece(result, shared, Direction.FORWARD) { method, premise, piece ->
                val entry = guidancePattern(piece)
                premise.forEachMember { member ->
                    shared.cancellation.checkpoint()
                    val from = guidancePattern(member.toPattern())
                    completion?.addBoundary(method, from, entry)
                    val pattern = DemandPattern(entry, from)
                    if (demand.add(method, pattern)) counts.merge(method, 1, Int::plus)
                }
            }
            projectTargets(result, shared, demand, counts)
            projectBlocks(result, shared, Direction.FORWARD, run1, demand, counts, completion)
            if (completion != null) {
                val projectionTime = projectionStart.elapsedNow()
                val indexStart = TimeSource.Monotonic.markNow()
                val frozen = completion.build()
                demand.withCompletion(frozen)
                for ((owner, view) in frozen.scopedViews()) demand.withCompletion(owner.method, owner.local, view)
                logger.info { "BIDI_STATIC_CLOSURE_FREEZE run=1 source=LOCAL_FROZEN_INPUT freezeTime=${completionStart.elapsedNow()} seedTime=$seedCaptureTime projectionTime=$projectionTime indexTime=${indexStart.elapsedNow()} ${frozen.statistics()}" }
            }
            val seeds = result.analyzers.flatMap { it.sinkSeeds }
            return demand.build() to SeedIndex.of(seeds)
        }

        private fun projectTargets(result: RunResult<RunMethodAnalyzer>, shared: SharedObjects,
                                   demand: DemandStore.Builder, counts: MutableMap<MethodKey, Int>) {
            for (actor in result.analyzers) for (row in actor.outgoingTargets) {
                shared.cancellation.checkpoint()
                for (member in row.premise.members) {
                    val exit = if (member.isZero) DemandExit.Zero
                        else DemandExit.Data(guidancePattern(member.toPattern()))
                    if (demand.add(actor.key, PairedDemand(DemandEntry.Target, exit)))
                        counts.merge(actor.key, 1, Int::plus)
                }
            }
        }

        private fun projectBlocks(result: RunResult<RunMethodAnalyzer>, shared: SharedObjects,
                                  direction: Direction, run1: Boolean,
                                  demand: DemandStore.Builder, counts: MutableMap<MethodKey, Int>,
                                  completion: FrozenStaticCompletion.Builder? = null) {
            projectBlockHandOff(shared.ap, direction, run1,
                result.analyzers.asSequence().flatMap { it.blockSummaries() },
                result.analyzers.asSequence().flatMap { it.blockOutgoingTargets() }, demand, counts,
                onBoundary = { key, from, to -> completion?.addScopedSeed(key, from, to) })
            if (run1 && completion != null) for (actor in result.analyzers)
                for (terminal in actor.blockOutgoingTargets()) for (row in terminal.rows) {
                    val original = checkNotNull(row.premise as? InitialAp) { "Run-1 cannot retain an ND original" }
                    completion.addScopedTarget(org.opentaint.dataflow.bidi.store.ScopedSummaryKey(
                        terminal.method, terminal.scope, terminal.exit), original.toPattern())
                }
        }

        private fun toForward(result: RunResult<RunMethodAnalyzer>, shared: SharedObjects,
                              counts: MutableMap<MethodKey, Int>): Pair<DemandStore, SeedIndex> {
            val demand = DemandStore.Builder(shared.ap)
            forEachDemandPiece(result, shared, Direction.BACKWARD) { method, premise, piece ->
                val pattern = when (premise) {
                    is InitialAp -> DemandPattern(guidancePattern(piece),
                        guidancePattern(premise.toPattern()))
                    is PremiseSet -> error("The backward run has no multi-premise summary (ap.md §9.2)")
                }
                if (demand.add(method, pattern)) counts.merge(method, 1, Int::plus)
            }
            projectTargets(result, shared, demand, counts)
            projectBlocks(result, shared, Direction.BACKWARD, false, demand, counts)
            val seeds = ArrayList<Seed>()
            for (actor in result.analyzers) {
                shared.cancellation.checkpoint()
                for ((method, statement, edge, action) in checkNotNull(actor.sourceHits).occurrences()) {
                    shared.cancellation.checkpoint()
                    seeds += Seed.Source(method, statement, edge, action)
                }
            }
            return demand.build() to SeedIndex.of(seeds)
        }
    }
}

/** Use the same predicate handle and literal seeds as the previous handoff. */
internal fun sinkSeedsFor(sink: SinkRule, method: MethodKey, at: CommonInst): List<Seed> = when {
    sink.predicate != null && !sink.unconditional ->
        listOf(Seed.PredicateSink(checkNotNull(sink.occurrenceId), method, at))
    sink.predicate != null -> emptyList()
    else -> sink.seedPatterns().map { Seed.Sink(sink.rule, method, at, it) }
}

/** GROUP evaluation must retain the original FULL seed patterns, as before.
 * Read the existing full form; do not keep a second seed or rule cache. */
internal fun fullSinkSeedsFor(shared: SharedObjects, sink: SinkRule,
                              method: MethodKey, at: CommonInst): List<Seed> {
    val seeds = LinkedHashSet<Seed>()
    withSinksAt(shared, method, at) { sinks ->
        for (full in sinks) {
            shared.cancellation.checkpoint()
            if (full.rule == sink.rule) seeds += sinkSeedsFor(full, method, at)
        }
    }
    return seeds.toList()
}

/** Existing full-form lookup used by sink handoff before terminal reporting. */
private fun withSinksAt(shared: SharedObjects, key: MethodKey, statement: CommonInst,
                       use: (List<SinkRule>) -> Unit) {
    val forms = shared.contexts.forms(key)
    val call = shared.language.getCallExpr(statement)
    if (call != null) forms.withCall(Direction.FORWARD, statement, call) { use(it.sinks) }
    else if (shared.interpreter.exitNodes(key).any {
        shared.cancellation.checkpoint(); it.node == statement
    }) forms.withExitRules(Direction.FORWARD, statement) { use(it.rules.sinks) }
}

package org.opentaint.dataflow.bidi.store

import org.opentaint.dataflow.bidi.ap.*
import org.opentaint.dataflow.util.Cancellation
import java.util.ArrayDeque
import java.util.IdentityHashMap

/** Current stored output annotations, not a history or a count of concrete
 * locations denoted by ANY. Shared DAG branches count at every field path.
 * Exact and ANY annotations are separate memberships. Scalar rows count one
 * stored TaintTree header/payload, including ZERO-origin concrete output.
 * Packed rows use one geometry plus exact masks and are counted directly. */
data class RelationCensus(
    val concreteOutputMemberships: Long = 0,
    val protectedOutputMemberships: Long = 0,
    val diagonalGeometryRows: Long = 0,
    val diagonalMarkRows: Long = 0,
    val scalarConcreteRows: Long = 0,
    val flowOutputAnnotations: Long = 0,
) {
    operator fun plus(other: RelationCensus): RelationCensus = RelationCensus(
        Math.addExact(concreteOutputMemberships, other.concreteOutputMemberships),
        Math.addExact(protectedOutputMemberships, other.protectedOutputMemberships),
        Math.addExact(diagonalGeometryRows, other.diagonalGeometryRows),
        Math.addExact(diagonalMarkRows, other.diagonalMarkRows),
        Math.addExact(scalarConcreteRows, other.scalarConcreteRows),
        Math.addExact(flowOutputAnnotations, other.flowOutputAnnotations),
    )

    companion object { val ZERO = RelationCensus() }
}

/** A completion-scan local cache. No node reference escapes into the returned
 * numeric result or remains on a store after census() returns. */
internal class RelationCensusCounter(private val cancellation: Cancellation) {
    private val flow = IdentityHashMap<FlowNode, Long>()
    private val taint = IdentityHashMap<TaintNode, Long>()
    init { cancellation.checkpoint() }

    fun flowAnnotations(root: FlowNode): Long = count(root, flow) { if (it.isEmpty) 0L else 1L }
    fun concreteMemberships(root: TaintNode): Long = count(root, taint) {
        it.exact.size.toLong() + it.any.size.toLong()
    }

    fun scalar(facts: Facts): RelationCensus {
        cancellation.checkpoint()
        return when (facts) {
            is Reach -> RelationCensus.ZERO
            is FlowTree -> RelationCensus(flowOutputAnnotations = flowAnnotations(facts.root))
            is TaintTree -> RelationCensus(
                concreteOutputMemberships = concreteMemberships(facts.root),
                protectedOutputMemberships = facts.nonSubsumable?.let(::concreteMemberships) ?: 0L,
                scalarConcreteRows = 1,
            )
        }
    }

    private class Frame<P : TrieLeaf>(val node: TrieNode<P>, var next: Int = 0)
    private fun <P : TrieLeaf> count(root: TrieNode<P>, memo: IdentityHashMap<TrieNode<P>, Long>,
                                    weight: (P) -> Long): Long {
        cancellation.checkpoint()
        memo[root]?.let { return it }
        val stack = ArrayDeque<Frame<P>>()
        stack.addLast(Frame(root))
        while (stack.isNotEmpty()) {
            cancellation.checkpoint()
            val frame = stack.peekLast()
            val children = frame.node.childData
            if (children != null && frame.next < children.size) {
                val child = children[frame.next++]
                if (!memo.containsKey(child)) stack.addLast(Frame(child))
                continue
            }
            var result = weight(frame.node.leaf)
            children?.forEach { child ->
                cancellation.checkpoint()
                // The same cached child can occur under two accessors. Add its
                // count twice: those accessors denote two different paths.
                result = Math.addExact(result, memo.getValue(child))
            }
            memo[frame.node] = result
            stack.removeLast()
        }
        return memo.getValue(root)
    }
}
